#!/usr/bin/env bash
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
python3 - <<'PY'
import base64
from pathlib import Path
data=base64.b64decode("""""")
p=Path("app/src/main/java/com/openai/thorbackfire/MainActivity.java")
p.write_bytes(data)
print("MainActivity v8 written:", len(data), "bytes")
PY
git add app/src/main/java/com/openai/thorbackfire/MainActivity.java
git commit -m "Add S63 aggressive RLM2 installer and restore"
git push
echo "DONE"
